.chat-detail-screen .input-action-bar-custom:has(.input-box-custom:placeholder-shown) .input-btns-right::before {
  content: "iMessage 信息" !important;
  position: absolute !important;
  left: 14px !important;              /* 精准对齐输入文字左侧起点 */
  top: 50% !important;
  transform: translateY(-50%) !important;

  /* 原生 iOS 占位文字质感 */
  font-size: 15px !important;
  font-weight: 400 !important;
  color: rgba(255, 255, 255, 0.42) !important;
  letter-spacing: -0.2px !important;
