/* == 我方气泡配色 == */
:root { --bubble-me-bg: #E5F9FF; }   
:root { --bubble-me-color: #1c1c1e; }。

/* == 文字图 == */

/* 1. 文字长图 / 模拟截图卡片外壳尺寸约束 */
.chat-detail-screen .msg-sim-card {
  max-width: 120px !important;         /* 最大宽度限制，避免撑爆横向屏幕 */
  max-height: 200px !important;        /* 最大高度限制，超长图不占满屏 */
  width: auto !important;
  border-radius: 18px !important;      /* 对齐 iMessage 气泡 18px 圆角 */
  overflow: hidden !important;         /* 超出范围平滑裁切 */
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25) !important;
  box-sizing: border-box !important;
}

/* 2. 文字图内部渲染的图片 (img)：比例自适应与自洽填充 */
.chat-detail-screen .msg-sim-card img {
  max-width: 100% !important;
  max-height: 200px !important;
  width: 100% !important;
  height: auto !important;
  object-fit: cover !important;        /* 顶部对齐裁剪展示精华部分 */
  object-position: top center !important;
  border-radius: inherit !important;
  display: block !important;
}

/* 3. 如果文字图是由 HTML 文本/代码块生成的模拟长图，允许其内部优雅截断 */
.chat-detail-screen .msg-sim-card [class*="content"],
.chat-detail-screen .msg-sim-card [class*="body"] {
  max-height: 200px !important;
  overflow: hidden !important;
}

/* 文字图背景 */
.msg-sim-card {
  background-color: #1c1c1e !important;   /* 图没加载出来时的底色 */
  background-image: url("https://i.ibb.co/0yxF8yL8/IMG-3819.jpg") !important;
  background-size: cover !important;       /* 铺满，不拉伸 */
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* 文字图：平时只显示背景图，点击才显示里面的内容 */
.msg-sim-card {
  cursor: pointer !important;                 /* 让苹果的浏览器把轻点当成「悬停」 */
  -webkit-tap-highlight-color: transparent;
  transition: box-shadow 0.25s ease;
}

/* 卡片里所有内容默认隐藏（只是变透明，卡片大小不变） */
.msg-sim-card > * {
  opacity: 0 !important;
  transition: opacity 0.25s ease !important;
}

/* 点击 / 按住 / 内部获得焦点时显示 */
.msg-sim-card:hover > *,
.msg-sim-card:active > *,
.msg-sim-card:focus-within > * {
  opacity: 1 !important;
}

/* 显示内容时给背景图盖一层暗色，保证字看得清；不想要就删掉这段，或把 0.35 调小 */
.msg-sim-card:hover,
.msg-sim-card:active,
.msg-sim-card:focus-within {
  box-shadow: inset 0 0 0 100vmax rgba(0, 0, 0, 0.35) !important;
}

/* 底栏内容整体上移，背景层不动 */
:root { --bar-lift: 14px; }   /* 上移多少，越大越高 */

.chat-detail-screen:not(:has([class*="checkbox"])) .input-row-wrapper {
  position: relative !important;
  top: calc(var(--bar-lift) * -1) !important;
}

/* 内容抬高了，消息区底部留白同步加上，最后一条消息不会被挡住 */
.chat-detail-screen .chat-messages-area {
  padding-bottom: calc(var(--input-area-min-height, 56px) + env(safe-area-inset-bottom, 44px) + 79px + var(--bar-lift)) !important;
}

