#chat-detail-screen .bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img)),
#chat-detail-screen .bubble-them-custom:has(.msg-transfer-card),
#chat-detail-screen .bubble-me-custom:has(.msg-transfer-card),
#chat-detail-screen .bubble-them-custom:has(.msg-loc-card),
#chat-detail-screen .bubble-me-custom:has(.msg-loc-card),
#chat-detail-screen .bubble-them-custom:has(.msg-sim-card),
#chat-detail-screen .bubble-me-custom:has(.msg-sim-card),
