.bubble-them-custom:has([class*="transfer"])::after,
.bubble-me-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
.bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
