/* == 文字图 == */

/* 1. 文字长图 / 模拟截图卡片外壳尺寸约束 */
.chat-detail-screen .msg-sim-card {
  max-width: 170px !important;         /* 最大宽度限制，避免撑爆横向屏幕 */
  max-height: 220px !important;        /* 最大高度限制，超长图不占满屏 */
  width: auto !important;
  border-radius: 18px !important; 
  overflow: hidden !important;         /* 超出范围平滑裁切 */
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25) !important;
  box-sizing: border-box !important;
}

/* 2. 文字图内部渲染的图片 (img)：比例自适应与自洽填充 */
.chat-detail-screen .msg-sim-card img {
  max-width: 170% !important;
  max-height: 220px !important;
  width: 200% !important;
  height: auto !important;
  object-fit: cover !important;        /* 顶部对齐裁剪展示精华部分 */
  object-position: top center !important;
  border-radius: inherit !important;
  display: block !important;
}

/* 3. 如果文字图是由 HTML 文本/代码块生成的模拟长图，允许其内部优雅截断 */
.chat-detail-screen .msg-sim-card [class*="content"],
.chat-detail-screen .msg-sim-card [class*="body"] {
  max-height: 200px !important;
  overflow: hidden !important;
}

/* 文字图背景 */
.msg-sim-card {
  background-color: #1c1c1e !important;   /* 图没加载出来时的底色 */
  background-image: url("https://i.ibb.co/20NrMfn1/IMG-5159.png") !important;
  background-size: cover !important;       /* 铺满，不拉伸 */
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* 文字图：平时只显示背景图，点击才显示里面的内容 */
.msg-sim-card {
  cursor: pointer !important;                 /* 让苹果的浏览器把轻点当成「悬停」 */
  -webkit-tap-highlight-color: transparent;
  transition: box-shadow 0.25s ease;
}

/* 卡片里所有内容默认隐藏（只是变透明，卡片大小不变） */
.msg-sim-card > * {
  opacity: 0 !important;
  transition: opacity 0.25s ease !important;
}

/* 点击 / 按住 / 内部获得焦点时显示 */
.msg-sim-card:hover > *,
.msg-sim-card:active > *,
.msg-sim-card:focus-within > * {
  opacity: 1 !important;
}

/* ===== 标题修复 先两边伸，右边到头后只往左伸 ===== */
:root{
  --chat-header-title-size:15px;
  --nj-hd-title-shift:80px;    /* 左边空白比右边多的宽度：短名字能否正好居中，就看它 */
}

.chat-detail-screen .header-profile-section{
  display:flex !important;
  flex-direction:row !important;
  align-items:center !important;
  flex:1 1 0 !important;
  min-width:0 !important;
  margin:0 !important;
  overflow:hidden !important;
}

/* 左边空白：比右边多 shift，名字一长它先缩 */
.chat-detail-screen .header-profile-section::before{
  content:"";
  flex:1 1000 var(--nj-hd-title-shift);
  min-width:0;
}
/* 右边空白：缩到 0 以后，名字右端就停在右边按钮前 */
.chat-detail-screen .header-profile-section::after{
  content:"";
  flex:1 1 0;
  min-width:0;
}

/* 放开标题外面所有容器可能有的宽度限制（截图里标题被卡在 138px 就是这个原因） */
.chat-detail-screen .header-profile-section *{
  max-width:none !important;
}
.chat-detail-screen .header-profile-section > *{
  flex:0 1 auto !important;
  min-width:0 !important;
  overflow:hidden !important;
}

.chat-detail-screen .chat-header-title{
  font-size:var(--chat-header-title-size) !important;
  white-space:nowrap !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  text-align:center !important;
}

/* 四个按钮不许被压缩 */
.chat-detail-screen :is(.header-btn-back,.header-btn-phone,.header-btn-video,.header-btn-info){
  flex:none !important;
}

/* 对方输入中：动画图按 15px 等比缩小，不裁切 */
#chat-detail-screen:has(.nuo-typing-indicator) .header-profile-section,
#chat-detail-screen:has(.nuo-typing-indicator) .header-profile-section > *{
  overflow:visible !important;
}
#chat-detail-screen:has(.nuo-typing-indicator) .chat-header-title::before{
  width:127.5px !important;
  height:23.3px !important;
  background-size:127.5px 23.3px !important;
}

/* ===== 电话按钮把位置让给标题，自己浮在标题上面（看不见，仍可点） ===== */
:root{
  --nj-hd-title-shift:44px;   /* 电话让位后，居中要用的数值从 80 变成了 44 */
}

.chat-detail-screen .header-btn-phone{
  margin-left:-36px !important;   /* 和按钮宽度一样：占位变成 0，按钮仍在原来的位置 */
  position:relative !important;
  z-index:5 !important;           /* 层级高于标题 */
}

/* ===== 标题宽度硬上限：长名字只能用省略号，不再挤右边按钮 ===== */
:root{
  --nj-hd-reserve:150px;   /* 两边按钮 + 边距占的总宽度：按钮还被挤就加大，省略号出现得太早就减小 */
}

.chat-detail-screen .header-profile-section{
  max-width:calc(100vw - var(--nj-hd-reserve)) !important;
}
.chat-detail-screen .header-profile-section .chat-header-title{
  max-width:calc(100vw - var(--nj-hd-reserve)) !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  white-space:nowrap !important;
}
